"""EntityProfile model — the agent's consolidated understanding of one entity.

The YAML file on disk is the artifact the user reads; this row indexes it so
the graph, search, and UI can query profiles without parsing every file.
"""


import uuid
from datetime import datetime

from sqlalchemy import DateTime, ForeignKey, Integer, String, Text
from sqlalchemy.dialects.postgresql import JSON, UUID
from sqlalchemy.orm import Mapped, mapped_column, relationship

from kairos_kb.db.base import Base


class EntityProfile(Base):
    """Semantic profile of a single entity, generated by the enrichment agent."""

    __tablename__ = "entity_profiles"

    workspace_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("workspaces.id", ondelete="CASCADE"), nullable=False, index=True
    )
    entity_id: Mapped[str] = mapped_column(String(1024), unique=True, nullable=False, index=True)
    kind: Mapped[str] = mapped_column(String(64), nullable=False, index=True)

    # Path of the YAML artifact within the storage backend.
    yaml_path: Mapped[str] = mapped_column(String(1024), nullable=False)

    # Denormalized headline fields, lifted out of the YAML for querying.
    summary: Mapped[str | None] = mapped_column(Text, nullable=True)
    purpose: Mapped[str | None] = mapped_column(Text, nullable=True)
    data_product: Mapped[str | None] = mapped_column(String(255), nullable=True)
    semantic_tags: Mapped[list | None] = mapped_column(JSON, nullable=True)

    # Hash of the source material the profile was derived from. Lets a re-run
    # skip entities whose underlying snapshot has not changed.
    source_hash: Mapped[str] = mapped_column(String(64), nullable=False, index=True)

    profile_version: Mapped[int] = mapped_column(Integer, nullable=False, default=1)
    model: Mapped[str | None] = mapped_column(String(128), nullable=True)
    run_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("enrichment_runs.id", ondelete="SET NULL"), nullable=True
    )
    generated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)

    workspace = relationship("Workspace", lazy="selectin")
